def load_master_key() -> bytes:
    """Load master key from env var, Keychain (macOS), or keyfile.

    Returns the raw Fernet key (base64-encoded 32 bytes).
    On non-macOS hosts a keyfile is auto-created if missing — server-side
    automation can't run ``vault-init`` interactively, and a brand-new
    install has no ciphertext yet, so generating one is safe.
    Raises VaultMissingKey only on macOS hosts that have neither env var
    nor a Keychain entry.
    """
    env_key = os.environ.get("AGENT_ML_MANAGER_VAULT_KEY")
    if env_key:
        return env_key.encode()

    if _is_macos():
        kc_key = _keychain_read()
        if kc_key:
            return kc_key.encode()
        # macOS: don't auto-init — operator is expected to run vault-init.
        raise VaultMissingKey(
            "No vault master key found. Run `agent-ml-manager vault-init` "
            "or set AGENT_ML_MANAGER_VAULT_KEY."
        )

    file_key = _keyfile_read()
    if file_key:
        return file_key.encode()

    new_key = Fernet.generate_key().decode()
    _keyfile_write(new_key)
    logger.warning(
        "vault: auto-created master key at %s — "
        "back this up; losing it makes all stored credentials unrecoverable",
        _keyfile_path(),
    )
    return new_key.encode()


def init_master_key(*, force: bool = False) -> str:
    """Generate a new Fernet key and store in Keychain (macOS) or keyfile.

    Returns the key as a base64 string (for the user to back up).
    Raises VaultError if a key already exists and force=False.
    """
    if _is_macos():
        if not force:
            existing = _keychain_read()
            if existing:
                raise VaultError(
                    "Vault master key already exists in Keychain. "
                    "Use force=True to overwrite."
                )
        key_str = Fernet.generate_key().decode()
        _keychain_write(key_str, force=force)
        return key_str

    if not force:
        existing = _keyfile_read()
        if existing:
            raise VaultError(
                f"Vault master key already exists at {_keyfile_path()}. "
                "Use force=True to overwrite."
            )
    key_str = Fernet.generate_key().decode()
    _keyfile_write(key_str)
    return key_str


def _get_fernet() -> Fernet:
    return Fernet(load_master_key())


def encrypt(plaintext: dict) -> bytes:
    """dict -> JSON -> Fernet ciphertext bytes."""
    data = json.dumps(plaintext, ensure_ascii=False).encode()
    return _get_fernet().encrypt(data)


def decrypt(ciphertext: bytes) -> dict:
    """Fernet ciphertext -> JSON -> dict. Raises VaultError on failure."""
    try:
        raw = _get_fernet().decrypt(ciphertext)
        return json.loads(raw)
    except (InvalidToken, json.JSONDecodeError) as exc:
        raise VaultError(f"Failed to decrypt credentials: {exc}") from exc


def store_credentials(server_id: str, creds: dict) -> Path:
    """Encrypt and write credentials to secrets/servers/<server_id>.enc."""
    d = _secrets_dir()
    d.mkdir(parents=True, exist_ok=True)
    path = d / f"{server_id}.enc"
    path.write_bytes(encrypt(creds))
    path.chmod(0o600)
    return path


def load_credentials(server_id: str) -> dict:
